//! Room content encryption shared by chat messages and file transfers.
//!
//! Envelopes are AES-256-GCM.  The room key is generated by the host and only
//! handed to clients after they have joined the room.  Legacy plaintext is
//! still readable so an older peer cannot break an existing room, but every
//! updated client asks for encrypted responses and uploads.

use base64::Engine;
use ring::{
    aead::{self, Aad, LessSafeKey, Nonce, UnboundKey},
    rand::{SecureRandom, SystemRandom},
};
use std::io::{self, Read, Write};

pub const TEXT_PREFIX: &str = "wbx1:";
const FILE_MAGIC: &[u8; 5] = b"WBXF1";
const NONCE_LEN: usize = 12;
const TAG_LEN: usize = 16;
const CHUNK_LEN: usize = 1024 * 1024;
const MIN_CHUNK_LEN: usize = 1024;
const MAX_CHUNK_LEN: usize = 8 * 1024 * 1024;
const HEADER_LEN: usize = FILE_MAGIC.len() + NONCE_LEN + 4;

pub fn generate_key() -> Result<String, String> {
    let mut bytes = [0u8; 32];
    SystemRandom::new()
        .fill(&mut bytes)
        .map_err(|_| "无法生成本机房间密钥".to_string())?;
    Ok(base64::engine::general_purpose::STANDARD.encode(bytes))
}

fn parse_key(key: &str) -> Result<LessSafeKey, String> {
    let bytes = base64::engine::general_purpose::STANDARD
        .decode(key.trim())
        .map_err(|_| "房间密钥格式无效".to_string())?;
    if bytes.len() != 32 {
        return Err("房间密钥长度无效".into());
    }
    UnboundKey::new(&aead::AES_256_GCM, &bytes)
        .map(LessSafeKey::new)
        .map_err(|_| "房间密钥无法使用".to_string())
}

fn random_nonce() -> Result<[u8; NONCE_LEN], String> {
    let mut nonce = [0u8; NONCE_LEN];
    SystemRandom::new()
        .fill(&mut nonce)
        .map_err(|_| "无法生成加密随机数".to_string())?;
    Ok(nonce)
}

fn chunk_nonce(base: &[u8; NONCE_LEN], index: u64) -> [u8; NONCE_LEN] {
    let mut nonce = *base;
    let mut counter = [0u8; 8];
    counter.copy_from_slice(&nonce[NONCE_LEN - 8..]);
    let value = u64::from_be_bytes(counter).wrapping_add(index);
    nonce[NONCE_LEN - 8..].copy_from_slice(&value.to_be_bytes());
    nonce
}

pub fn message_aad(room_id: &str) -> String {
    format!("wenbox-message:v1:{room_id}")
}

pub fn file_aad(room_id: &str) -> String {
    format!("wenbox-file:v1:{room_id}")
}

pub fn encrypt_text(key: &str, aad: &str, plaintext: &str) -> Result<String, String> {
    let key = parse_key(key)?;
    let nonce = random_nonce()?;
    let mut data = plaintext.as_bytes().to_vec();
    key.seal_in_place_append_tag(
        Nonce::assume_unique_for_key(nonce),
        Aad::from(aad.as_bytes()),
        &mut data,
    )
    .map_err(|_| "消息加密失败".to_string())?;
    let mut envelope = Vec::with_capacity(NONCE_LEN + data.len());
    envelope.extend_from_slice(&nonce);
    envelope.extend_from_slice(&data);
    Ok(format!(
        "{TEXT_PREFIX}{}",
        base64::engine::general_purpose::STANDARD.encode(envelope)
    ))
}

/// Decrypt a text envelope.  Plaintext without the marker is returned as-is
/// for compatibility with peers built before room content encryption.
pub fn decrypt_text(key: &str, aad: &str, value: &str) -> Result<String, String> {
    let Some(encoded) = value.strip_prefix(TEXT_PREFIX) else {
        return Ok(value.to_string());
    };
    let mut envelope = base64::engine::general_purpose::STANDARD
        .decode(encoded)
        .map_err(|_| "消息密文格式无效".to_string())?;
    if envelope.len() < NONCE_LEN + TAG_LEN {
        return Err("消息密文长度无效".into());
    }
    let (nonce, data) = envelope.split_at_mut(NONCE_LEN);
    let key = parse_key(key)?;
    let plaintext = key
        .open_in_place(
            Nonce::try_assume_unique_for_key(nonce).map_err(|_| "消息随机数无效".to_string())?,
            Aad::from(aad.as_bytes()),
            data,
        )
        .map_err(|_| "消息解密失败，可能不是本房间的内容".to_string())?;
    String::from_utf8(plaintext.to_vec()).map_err(|_| "消息内容不是有效文本".to_string())
}

/// Serialize an encrypted file stream into `writer`.
pub fn stream_encrypt<R: Read, W: Write>(
    key: &str,
    room_id: &str,
    reader: &mut R,
    writer: &mut W,
) -> Result<u64, String> {
    let key = parse_key(key)?;
    let base = random_nonce()?;
    writer
        .write_all(FILE_MAGIC)
        .and_then(|_| writer.write_all(&base))
        .and_then(|_| writer.write_all(&(CHUNK_LEN as u32).to_be_bytes()))
        .map_err(|e| format!("写入加密文件头失败: {e}"))?;
    let mut chunk = vec![0u8; CHUNK_LEN];
    let mut total = 0u64;
    let mut index = 0u64;
    loop {
        let count = read_chunk(reader, &mut chunk)?;
        let final_chunk = count == 0;
        let mut data = chunk[..count].to_vec();
        let aad = format!("{}:{}", file_aad(room_id), index);
        key.seal_in_place_append_tag(
            Nonce::assume_unique_for_key(chunk_nonce(&base, index)),
            Aad::from(aad.as_bytes()),
            &mut data,
        )
        .map_err(|_| "文件加密失败".to_string())?;
        let len = u32::try_from(data.len()).map_err(|_| "文件分块过大".to_string())?;
        writer
            .write_all(&len.to_be_bytes())
            .and_then(|_| writer.write_all(&data))
            .map_err(|e| format!("写入加密文件失败: {e}"))?;
        total += count as u64;
        index += 1;
        if final_chunk {
            break;
        }
    }
    Ok(total)
}

/// Decrypt an encrypted file stream into `writer`, returning plaintext size.
pub fn stream_decrypt<R: Read, W: Write>(
    key: &str,
    room_id: &str,
    reader: &mut R,
    writer: &mut W,
) -> Result<u64, String> {
    let key = parse_key(key)?;
    let mut header = [0u8; HEADER_LEN];
    reader
        .read_exact(&mut header)
        .map_err(|_| "加密文件头不完整".to_string())?;
    if &header[..FILE_MAGIC.len()] != FILE_MAGIC {
        return Err("文件未使用受支持的加密格式".into());
    }
    let mut base = [0u8; NONCE_LEN];
    base.copy_from_slice(&header[FILE_MAGIC.len()..FILE_MAGIC.len() + NONCE_LEN]);
    let chunk_len = u32::from_be_bytes(
        header[FILE_MAGIC.len() + NONCE_LEN..]
            .try_into()
            .map_err(|_| "加密文件块大小无效".to_string())?,
    ) as usize;
    if !(MIN_CHUNK_LEN..=MAX_CHUNK_LEN).contains(&chunk_len) {
        return Err("加密文件块大小超出范围".into());
    }
    let mut total = 0u64;
    let mut index = 0u64;
    loop {
        let mut len = [0u8; 4];
        match reader.read_exact(&mut len) {
            Ok(()) => {}
            Err(error) if error.kind() == io::ErrorKind::UnexpectedEof => {
                return Err("加密文件缺少结束校验".into())
            }
            Err(error) => return Err(format!("读取加密文件失败: {error}")),
        }
        let len = u32::from_be_bytes(len) as usize;
        if !(TAG_LEN..=chunk_len + TAG_LEN).contains(&len) {
            return Err("加密文件分块长度无效".into());
        }
        let mut data = vec![0u8; len];
        reader
            .read_exact(&mut data)
            .map_err(|_| "加密文件分块不完整".to_string())?;
        let aad = format!("{}:{}", file_aad(room_id), index);
        let plaintext = key
            .open_in_place(
                Nonce::assume_unique_for_key(chunk_nonce(&base, index)),
                Aad::from(aad.as_bytes()),
                &mut data,
            )
            .map_err(|_| "文件解密失败，可能不是本房间的内容".to_string())?;
        if plaintext.is_empty() {
            let mut extra = [0u8; 1];
            if reader.read(&mut extra).map_err(|e| e.to_string())? != 0 {
                return Err("加密文件结束后包含额外数据".into());
            }
            return Ok(total);
        }
        writer
            .write_all(plaintext)
            .map_err(|e| format!("写入解密文件失败: {e}"))?;
        total += plaintext.len() as u64;
        index += 1;
    }
}

fn read_chunk<R: Read>(reader: &mut R, chunk: &mut [u8]) -> Result<usize, String> {
    let mut filled = 0;
    while filled < chunk.len() {
        match reader.read(&mut chunk[filled..]) {
            Ok(0) => break,
            Ok(count) => filled += count,
            Err(error) if error.kind() == io::ErrorKind::Interrupted => continue,
            Err(error) => return Err(format!("读取文件失败: {error}")),
        }
    }
    Ok(filled)
}

/// Streaming encrypting reader used for HTTP downloads.  It emits the same
/// framed format as `stream_encrypt` without buffering the whole file.
pub struct EncryptReader<R> {
    reader: R,
    key: LessSafeKey,
    room_id: String,
    base: [u8; NONCE_LEN],
    index: u64,
    pending: Vec<u8>,
    offset: usize,
    header_sent: bool,
    finished: bool,
}

impl<R: Read> EncryptReader<R> {
    pub fn new(reader: R, key: &str, room_id: &str) -> Result<Self, String> {
        Ok(Self {
            reader,
            key: parse_key(key)?,
            room_id: room_id.to_string(),
            base: random_nonce()?,
            index: 0,
            pending: Vec::new(),
            offset: 0,
            header_sent: false,
            finished: false,
        })
    }

    fn fill(&mut self) -> io::Result<()> {
        if !self.header_sent {
            self.pending = Vec::with_capacity(HEADER_LEN);
            self.pending.extend_from_slice(FILE_MAGIC);
            self.pending.extend_from_slice(&self.base);
            self.pending
                .extend_from_slice(&(CHUNK_LEN as u32).to_be_bytes());
            self.header_sent = true;
            return Ok(());
        }
        if self.finished {
            self.pending.clear();
            return Ok(());
        }
        let mut chunk = vec![0u8; CHUNK_LEN];
        let count = read_chunk(&mut self.reader, &mut chunk).map_err(io::Error::other)?;
        if count == 0 {
            self.finished = true;
        }
        chunk.truncate(count);
        let aad = format!("{}:{}", file_aad(&self.room_id), self.index);
        self.key
            .seal_in_place_append_tag(
                Nonce::assume_unique_for_key(chunk_nonce(&self.base, self.index)),
                Aad::from(aad.as_bytes()),
                &mut chunk,
            )
            .map_err(|_| io::Error::other("文件加密失败"))?;
        self.index += 1;
        let mut framed = Vec::with_capacity(4 + chunk.len());
        framed.extend_from_slice(&(chunk.len() as u32).to_be_bytes());
        framed.extend_from_slice(&chunk);
        self.pending = framed;
        Ok(())
    }
}

impl<R: Read> Read for EncryptReader<R> {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        if self.offset >= self.pending.len() {
            self.fill()?;
            self.offset = 0;
        }
        if self.offset >= self.pending.len() {
            return Ok(0);
        }
        let available = self.pending.len() - self.offset;
        let count = available.min(buf.len());
        buf[..count].copy_from_slice(&self.pending[self.offset..self.offset + count]);
        self.offset += count;
        Ok(count)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn file_truncation_at_frame_boundary_is_rejected() {
        let key = generate_key().unwrap();
        let mut wire = Vec::new();
        stream_encrypt(&key, "room", &mut &b"file"[..], &mut wire).unwrap();
        for end in [HEADER_LEN, wire.len() - 20, wire.len() - 1] {
            assert!(stream_decrypt(&key, "room", &mut &wire[..end], &mut Vec::new()).is_err());
        }
    }
    #[test]
    fn text_roundtrip_is_bound_to_the_room() {
        let key = generate_key().unwrap();
        let encrypted = encrypt_text(&key, &message_aad("room-a"), "你好 WenBox").unwrap();
        assert!(encrypted.starts_with(TEXT_PREFIX));
        assert_eq!(
            decrypt_text(&key, &message_aad("room-a"), &encrypted).unwrap(),
            "你好 WenBox"
        );
        assert!(decrypt_text(&key, &message_aad("room-b"), &encrypted).is_err());
        assert_eq!(
            decrypt_text(&key, &message_aad("room-a"), "legacy plaintext").unwrap(),
            "legacy plaintext"
        );
    }

    #[test]
    fn file_stream_roundtrip_survives_chunk_boundaries() {
        let key = generate_key().unwrap();
        let input = (0..(CHUNK_LEN * 2 + 37))
            .map(|i| (i % 251) as u8)
            .collect::<Vec<_>>();
        let mut encrypted = Vec::new();
        let written =
            stream_encrypt(&key, "room-a", &mut input.as_slice(), &mut encrypted).unwrap();
        assert_eq!(written, input.len() as u64);
        assert!(encrypted.starts_with(FILE_MAGIC));
        let mut decrypted = Vec::new();
        let read =
            stream_decrypt(&key, "room-a", &mut encrypted.as_slice(), &mut decrypted).unwrap();
        assert_eq!(read, input.len() as u64);
        assert_eq!(decrypted, input);
    }

    #[test]
    fn encrypt_reader_matches_stream_format() {
        let key = generate_key().unwrap();
        let input = b"streaming download body".repeat(1000);
        let mut reader = EncryptReader::new(input.as_slice(), &key, "room-a").unwrap();
        let mut encrypted = Vec::new();
        reader.read_to_end(&mut encrypted).unwrap();
        let mut decrypted = Vec::new();
        let read =
            stream_decrypt(&key, "room-a", &mut encrypted.as_slice(), &mut decrypted).unwrap();
        assert_eq!(read, input.len() as u64);
        assert_eq!(decrypted, input);
    }

    #[test]
    fn decrypts_the_browser_noble_aes_gcm_vector() {
        // Generated by app/src/main/assets/web/aes-gcm.js with a fixed key,
        // nonce and AAD.  This guards the Web fallback used on insecure LAN
        // HTTP origins against format drift from the Rust implementation.
        let key = "AQIDBAUGBwgJCgsMDQ4PEBESExQVFhcYGRobHB0eHyA=";
        let value = "wbx1:yMfGxcTDwsHAv769HIDaVhYBEmIvNXuzdTazgAvkBvgzO1RRyqn2vQ==";
        assert_eq!(
            decrypt_text(key, &message_aad("room-test"), value).unwrap(),
            "跨端互通"
        );
    }

    #[test]
    fn decrypts_the_browser_noble_file_frame() {
        // Generated by app/src/main/assets/web/aes-gcm.js using the WBXF1
        // framing, fixed key/base nonce and chunk index 0.
        let key = "AQIDBAUGBwgJCgsMDQ4PEBESExQVFhcYGRobHB0eHyA=";
        let frame = base64::engine::general_purpose::STANDARD
            .decode("V0JYRjFkZWZnaGlqa2xtbm8AEAAAAAAAIwY2Hym869INnSXA6DXKTbccMI2pAeFgpXyHyTv8t+DoAWqfAAAAEItrXq62CXL/JhZ8HbZp0AM=")
            .unwrap();
        let mut decrypted = Vec::new();
        stream_decrypt(key, "room-test", &mut frame.as_slice(), &mut decrypted).unwrap();
        assert_eq!(decrypted, "file-interop-测试".as_bytes());
    }
}
